// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// 本域进程存活
	// (GET /healthz)
	Health(ctx context.Context, request HealthRequestObject) (HealthResponseObject, error)
	// 本域启动/恢复就绪
	// (GET /readyz)
	Ready(ctx context.Context, request ReadyRequestObject) (ReadyResponseObject, error)
	// 取得本地维护屏障
	// (POST /v1/barriers)
	AcquireBarrier(ctx context.Context, request AcquireBarrierRequestObject) (AcquireBarrierResponseObject, error)
	// 释放已授权维护屏障
	// (POST /v1/barriers/{barrierId}:release)
	ReleaseBarrier(ctx context.Context, request ReleaseBarrierRequestObject) (ReleaseBarrierResponseObject, error)
	// 列入库任务
	// (GET /v1/builds)
	ListBuilds(ctx context.Context, request ListBuildsRequestObject) (ListBuildsResponseObject, error)
	// 人工或事件申请构建
	// (POST /v1/builds)
	CreateBuild(ctx context.Context, request CreateBuildRequestObject) (CreateBuildResponseObject, error)
	// 读取入库状态
	// (GET /v1/builds/{buildId})
	GetBuild(ctx context.Context, request GetBuildRequestObject) (GetBuildResponseObject, error)
	// 取消入库链路
	// (POST /v1/builds/{buildId}/cancel)
	CancelBuild(ctx context.Context, request CancelBuildRequestObject) (CancelBuildResponseObject, error)
	// 返回安全诊断
	// (GET /v1/builds/{buildId}/diagnostics)
	RedactDiagnostics(ctx context.Context, request RedactDiagnosticsRequestObject) (RedactDiagnosticsResponseObject, error)
	// 按文档读取全部分块
	// (POST /v1/document-chunks:read)
	ReadDocumentChunks(ctx context.Context, request ReadDocumentChunksRequestObject) (ReadDocumentChunksResponseObject, error)
	// 读取文档索引视图
	// (POST /v1/document-index:read)
	ReadDocumentIndex(ctx context.Context, request ReadDocumentIndexRequestObject) (ReadDocumentIndexResponseObject, error)
	// 快速检索员有限核查
	// (POST /v1/evidence:inspect)
	InspectEvidence(ctx context.Context, request InspectEvidenceRequestObject) (InspectEvidenceResponseObject, error)
	// 读取索引配置
	// (GET /v1/index-config)
	ReadIndexConfig(ctx context.Context, request ReadIndexConfigRequestObject) (ReadIndexConfigResponseObject, error)
	// 更新索引配置
	// (PUT /v1/index-config)
	PutIndexConfig(ctx context.Context, request PutIndexConfigRequestObject) (PutIndexConfigResponseObject, error)
	// 读取知识管理真实选项
	// (GET /v1/index-options)
	ReadIndexOptions(ctx context.Context, request ReadIndexOptionsRequestObject) (ReadIndexOptionsResponseObject, error)
	// 读取原知识任务恢复证明
	// (POST /v1/jobs/{jobId}/recovery)
	ReadJobRecovery(ctx context.Context, request ReadJobRecoveryRequestObject) (ReadJobRecoveryResponseObject, error)
	// 统一生成并复用查询嵌入
	// (POST /v1/query-embeddings)
	CreateQueryEmbedding(ctx context.Context, request CreateQueryEmbeddingRequestObject) (CreateQueryEmbeddingResponseObject, error)
	// 估算全量重建费用
	// (POST /v1/rebuild-plans)
	EstimateRebuildPlan(ctx context.Context, request EstimateRebuildPlanRequestObject) (EstimateRebuildPlanResponseObject, error)
	// 批准全量重建
	// (POST /v1/rebuild-plans/{planId}:approve)
	ApproveRebuildPlan(ctx context.Context, request ApproveRebuildPlanRequestObject) (ApproveRebuildPlanResponseObject, error)
	// 统一混合检索
	// (POST /v1/retrievals)
	SearchKnowledge(ctx context.Context, request SearchKnowledgeRequestObject) (SearchKnowledgeResponseObject, error)
	// 按引用读取证据片段
	// (POST /v1/sections:read)
	ReadSections(ctx context.Context, request ReadSectionsRequestObject) (ReadSectionsResponseObject, error)
	// 读取全站概括
	// (POST /v1/site-overview:read)
	ReadSiteOverview(ctx context.Context, request ReadSiteOverviewRequestObject) (ReadSiteOverviewResponseObject, error)
	// 立即重算全站概括
	// (POST /v1/site-overview:refresh)
	RefreshSiteOverview(ctx context.Context, request RefreshSiteOverviewRequestObject) (RefreshSiteOverviewResponseObject, error)
	// 受控读取已完成域快照归档
	// (GET /v1/snapshots/{snapshotId}/archive)
	ReadSnapshotArchive(ctx context.Context, request ReadSnapshotArchiveRequestObject) (ReadSnapshotArchiveResponseObject, error)
	// 删除恢复暂存或换出的旧数据目录
	// (POST /v1/snapshots:discard)
	DiscardSnapshot(ctx context.Context, request DiscardSnapshotRequestObject) (DiscardSnapshotResponseObject, error)
	// 导出安全watermark快照
	// (POST /v1/snapshots:export)
	ExportSnapshot(ctx context.Context, request ExportSnapshotRequestObject) (ExportSnapshotResponseObject, error)
	// 暂存本域恢复归档，不改active目录
	// (POST /v1/snapshots:stage)
	StageSnapshot(ctx context.Context, request StageSnapshotRequestObject) (StageSnapshotResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

